

// ===== CONTROL DE ACCESO COMPARTIDO (SERVIDOR) =====
(function(){
  let currentLoggedUser = null;
  let currentLoggedRole = null;
  let currentLoggedDisplayName = null;
  let authToken = sessionStorage.getItem('pnp_auth_token') || '';

  async function api(path, options={}){
    options.headers = Object.assign({'Content-Type':'application/json'}, options.headers||{});
    if(authToken) options.headers.Authorization='Bearer '+authToken;
    const r=await fetch(path, options);
    let data={};
    try{ data=await r.json(); }catch(e){}
    if(!r.ok) throw new Error(data.error || 'Error del servidor');
    return data;
  }
  function showError(t){document.getElementById('auth-error').textContent=t||'';}
  // Mostrar el mismo avatar policial en la pantalla principal de acceso.
  // El avatar del encabezado está embebido en el HTML, así que no depende de
  // una ruta externa que pueda romperse al desplegar en Render.
  function setAuthAvatar(){
    const authAvatar=document.getElementById('auth-avatar');
    const headerAvatar=document.querySelector('.header-avatar');
    if(authAvatar && headerAvatar && headerAvatar.src){
      authAvatar.src=headerAvatar.src;
      authAvatar.style.display='block';
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',setAuthAvatar);
  else setAuthAvatar();
  function enter(user, role){
    currentLoggedUser=user;
    currentLoggedRole=role||currentLoggedRole;
    const displayName=sessionStorage.getItem('pnp_display_name')||user;
    currentLoggedDisplayName=displayName;
    sessionStorage.setItem('pnp_session_user',user);
    sessionStorage.setItem('pnp_session_role',currentLoggedRole||'user');
    sessionStorage.setItem('pnp_display_name',displayName);
    document.getElementById('auth-screen').style.display='none';
    document.body.style.overflow='';
    const adminBar=document.getElementById('admin-main-bar');
    if(adminBar) adminBar.style.display=(currentLoggedRole==='admin'?'block':'none');
    const banner=document.getElementById('logged-user-banner');
    if(banner){ banner.style.display='block'; document.getElementById('logged-user-name').textContent=displayName; document.getElementById('logged-user-login').textContent='Usuario: '+user; renderMyRecentExams(); }
  }
  async function login(){
    const u=document.getElementById('auth-user').value.trim();
    const p=document.getElementById('auth-pass').value;
    if(!u||!p){showError('Ingrese usuario y contraseña.');return;}
    try{
      const data=await api('/api/login',{method:'POST',body:JSON.stringify({username:u,password:p})});
      authToken=data.token; currentLoggedUser=data.username; currentLoggedRole=data.role; currentLoggedDisplayName=data.display_name||data.username;
      sessionStorage.setItem('pnp_auth_token',authToken);
      sessionStorage.setItem('pnp_session_user',currentLoggedUser);
      sessionStorage.setItem('pnp_display_name',currentLoggedDisplayName);
      showError(''); enter(currentLoggedUser,currentLoggedRole);
    }catch(e){showError(e.message);}
  }

  async function renderMyRecentExams(){
    const box=document.getElementById('my-recent-exams'); if(!box)return;
    try{
      const data=await api('/api/my-history'); const exams=(data.exams||[]).slice(0,5);
      box.innerHTML=exams.length ? exams.map(x=>{const ok=Number(x.score)>=65;return `<div class="mini-exam"><span class="mini-exam-date">${escAuth(formatShortDate(x.fecha))}</span><span class="mini-exam-score">${escAuth(x.score)} PTOS</span><span class="mini-exam-status ${ok?'status-ok':'status-bad'}">${ok?'APROBADO':'DESAPROBADO'}</span></div>`;}).join('') : '<span class="no-exams">Aún no has realizado exámenes</span>';
    }catch(e){box.innerHTML='<span class="no-exams">No se pudo cargar el historial</span>';}
  }

  async function renderUsers(){
    const list=document.getElementById('user-list'); if(!list)return;
    try{
      const data=await api('/api/users');
      list.innerHTML='';
      data.users.forEach(user=>{
        const row=document.createElement('div');row.className='user-item';
        const main=document.createElement('div');main.className='user-main';
        main.innerHTML='<span class="user-name">'+escAuth(user.display_name || user.username)+'</span><span class="user-login">Usuario: '+escAuth(user.username)+'</span>';
        row.appendChild(main);
        const exams=document.createElement('div');exams.className='user-exams';
        const recent=(user.recent_exams||[]).slice(0,5);
        exams.innerHTML=recent.length ? recent.map(x=>{const ok=Number(x.score)>=65;return '<div class="mini-exam"><span class="mini-exam-date">'+escAuth(formatShortDate(x.fecha))+'</span><span class="mini-exam-score">'+escAuth(x.score)+' PTOS</span><span class="mini-exam-status '+(ok?'status-ok':'status-bad')+'">'+(ok?'APROBADO':'DESAPROBADO')+'</span></div>';}).join('') : '<span class="no-exams">Sin exámenes realizados</span>';
        row.appendChild(exams);
        if(user.username!=='admin'){
          const btn=document.createElement('button');btn.className='auth-danger';btn.textContent='Eliminar';
          btn.onclick=async()=>{if(confirm('¿Eliminar '+user.username+'?')){try{await api('/api/users/'+encodeURIComponent(user.username),{method:'DELETE'});renderUsers();}catch(e){alert(e.message);}}};
          row.appendChild(btn);
        }
        list.appendChild(row);
      });
    }catch(e){list.innerHTML='<div class="auth-small">'+e.message+'</div>';}
  }

  async function renderHistory(){
    const list=document.getElementById('history-list'); const summary=document.getElementById('history-summary');
    if(!list||!summary)return;
    try{
      const data=await api('/api/history'); const h=data.history.slice().reverse();
      const accesses=h.filter(x=>x.type==='access').length, exams=h.filter(x=>x.type==='result').length;
      summary.textContent='Registros: '+h.length+' · Accesos: '+accesses+' · Exámenes terminados: '+exams;
      if(!h.length){list.innerHTML='<div class="auth-small">Todavía no hay registros.</div>';return;}
      let rows=h.map(x=>{
        if(x.type==='access') return '<tr><td>'+escAuth(x.fecha)+'</td><td>'+escAuth(x.usuario)+'</td><td>Ingreso</td><td>—</td><td class="history-ok">Acceso correcto</td></tr>';
        const estado=x.score>=65?'Aprobado':'No aprobado', cls=x.score>=65?'history-ok':'history-bad';
        return '<tr><td>'+escAuth(x.fecha)+'</td><td>'+escAuth(x.usuario)+'</td><td>Examen</td><td>'+x.score+'/100 ('+x.pct+'%)</td><td class="'+cls+'">'+estado+'</td></tr>';
      }).join('');
      list.innerHTML='<table class="auth-table"><thead><tr><th>Fecha/hora</th><th>Usuario</th><th>Evento</th><th>Resultado</th><th>Estado</th></tr></thead><tbody>'+rows+'</tbody></table>';
    }catch(e){list.innerHTML='<div class="auth-small">'+e.message+'</div>';}
  }
  function escAuth(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

  document.getElementById('auth-login').onclick=login;
  ['auth-user','auth-pass'].forEach(id=>document.getElementById(id).addEventListener('keydown',e=>{if(e.key==='Enter')login();}));

  const toggle=document.getElementById('admin-toggle'), panel=document.getElementById('admin-panel');
  let adminOpen=false;

  async function ensureAdminSession(){
    // Si ya hay una sesión válida de administrador, úsala.
    if(authToken){
      try{
        const me=await api('/api/me');
        if(me.role==='admin') return true;
      }catch(e){}
    }

    // Si no hay sesión de administrador, solicita las credenciales.
    const adminUser=prompt('Usuario de administrador:', 'admin');
    if(adminUser===null) return false;
    const adminPass=prompt('Contraseña de administrador:');
    if(adminPass===null) return false;

    try{
      const data=await api('/api/login',{
        method:'POST',
        body:JSON.stringify({username:adminUser.trim(),password:adminPass})
      });
      if(data.role!=='admin'){
        alert('Ese usuario no tiene permisos de administrador.');
        return false;
      }
      authToken=data.token;
      currentLoggedUser=data.username;
      currentLoggedRole=data.role;
      currentLoggedDisplayName=data.display_name||data.username;
      sessionStorage.setItem('pnp_auth_token',authToken);
      sessionStorage.setItem('pnp_session_user',currentLoggedUser);
      return true;
    }catch(e){
      alert(e.message);
      return false;
    }
  }

  toggle.onclick=async()=>{
    if(!adminOpen){
      const ok=await ensureAdminSession();
      if(!ok) return;
      try{
        panel.style.display='block';
        adminOpen=true;
        toggle.textContent='Ocultar administración';
        await renderUsers();
        await renderHistory();
      }catch(e){
        alert(e.message);
      }
    }else{
      panel.style.display='none';
      adminOpen=false;
      toggle.textContent='Administrar usuarios';
    }
  };

  document.getElementById('add-user').onclick=async()=>{
    const n=document.getElementById('new-name').value.trim(), u=document.getElementById('new-user').value.trim(), p=document.getElementById('new-pass').value;
    if(!n||!u||!p){alert('Complete nombre, usuario y contraseña.');return;}
    try{await api('/api/users',{method:'POST',body:JSON.stringify({nombre:n,display_name:n,username:u,password:p})});document.getElementById('new-name').value='';document.getElementById('new-user').value='';document.getElementById('new-pass').value='';await renderUsers();}
    catch(e){alert(e.message);}
  };
  document.getElementById('unbind-device').style.display='none';
  document.getElementById('refresh-history').onclick=renderHistory;
  document.getElementById('clear-history').onclick=async()=>{
    if(confirm('¿Borrar todo el historial de accesos y resultados?')){try{await api('/api/history',{method:'DELETE'});await renderHistory();}catch(e){alert(e.message);}}
  };

  // Panel de administración dentro de la página principal
  function escMain(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  function formatShortDate(v){ if(!v) return 'Sin fecha'; const d=new Date(v); if(Number.isNaN(d.getTime())) return String(v); return new Intl.DateTimeFormat('es-PE',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d); }
  async function mainRenderUsers(){
    const list=document.getElementById('main-user-list'); if(!list)return;
    try{
      const data=await api('/api/users');
      if(!data.users.length){list.innerHTML='<div class="auth-small">No hay usuarios creados.</div>';return;}
      list.innerHTML=data.users.map(u=>{
        const exams=(u.recent_exams||[]).slice(0,5);
        const examHtml=exams.length ? exams.map(x=>{const ok=Number(x.score)>=65;return `<div class="mini-exam"><span class="mini-exam-date">${escMain(formatShortDate(x.fecha))}</span><span class="mini-exam-score">${escMain(x.score)} PTOS</span><span class="mini-exam-status ${ok?'status-ok':'status-bad'}">${ok?'APROBADO':'DESAPROBADO'}</span></div>`;}).join('') : '<span class="no-exams">Sin exámenes realizados</span>';
        return `<div class="user-item"><div class="user-main"><span class="user-name">${escMain(u.display_name||u.username)}</span><span class="user-login">Usuario: ${escMain(u.username)}</span></div><div class="user-exams">${examHtml}</div><div>${u.username!=='admin'?`<button class="auth-danger" data-del-user="${escMain(u.username)}">Eliminar</button>`:''}</div></div>`;
      }).join('');
      list.querySelectorAll('[data-del-user]').forEach(btn=>btn.onclick=async()=>{const u=btn.getAttribute('data-del-user');if(!confirm('¿Eliminar '+u+'?'))return;try{await api('/api/users/'+encodeURIComponent(u),{method:'DELETE'});await mainRenderUsers();}catch(e){alert(e.message);}});
    }catch(e){list.innerHTML='<div class="auth-small">'+escMain(e.message)+'</div>';}
  }
  async function mainRenderHistory(){
    const list=document.getElementById('main-history-list'); if(!list)return;
    try{
      const data=await api('/api/history'); const h=(data.history||[]).slice().reverse();
      if(!h.length){list.innerHTML='<div class="auth-small">Todavía no hay exámenes ni accesos registrados.</div>';return;}
      const rows=h.map(x=>{
        if(x.type==='access') return `<tr><td>${escMain(x.fecha)}</td><td>${escMain(x.usuario)}</td><td>Ingreso</td><td>—</td></tr>`;
        const ok=Number(x.score)>=65; return `<tr><td>${escMain(x.fecha)}</td><td>${escMain(x.usuario)}</td><td>Examen</td><td>${escMain(x.score)} PTOS</td><td class="${ok?'history-ok':'history-bad'}">${ok?'APROBADO':'DESAPROBADO'}</td></tr>`;
      }).join('');
      list.innerHTML='<table class="auth-table"><thead><tr><th>Fecha/hora</th><th>Usuario</th><th>Evento</th><th>Nota</th><th>Estado</th></tr></thead><tbody>'+rows+'</tbody></table>';
    }catch(e){list.innerHTML='<div class="auth-small">'+escMain(e.message)+'</div>';}
  }
  document.getElementById('admin-main-toggle').onclick=async()=>{
    const panel=document.getElementById('admin-main-panel');
    const open=panel.style.display==='block';
    panel.style.display=open?'none':'block';
    if(!open){await mainRenderUsers();await mainRenderHistory();}
  };
  document.getElementById('main-add-user').onclick=async()=>{
    const n=document.getElementById('main-new-name').value.trim(), u=document.getElementById('main-new-user').value.trim(), p=document.getElementById('main-new-pass').value, msg=document.getElementById('main-user-msg');
    msg.textContent='';
    if(!n||!u||!p){msg.textContent='Escribe nombre, usuario y contraseña.';return;}
    try{await api('/api/users',{method:'POST',body:JSON.stringify({nombre:n,display_name:n,username:u,password:p})});document.getElementById('main-new-name').value='';document.getElementById('main-new-user').value='';document.getElementById('main-new-pass').value='';msg.textContent='Usuario creado correctamente.';await mainRenderUsers();}
    catch(e){msg.textContent=e.message;}
  };
  document.getElementById('main-refresh-history').onclick=mainRenderHistory;

  // No auto-login: credentials are requested again when the page opens.
  sessionStorage.removeItem('pnp_auth_token');
  sessionStorage.removeItem('pnp_session_user');
  authToken=''; currentLoggedUser=null; currentLoggedRole=null; currentLoggedDisplayName=null; sessionStorage.removeItem('pnp_display_name');
})();

// Decode questions from base64 to avoid JS string escaping issues
const B64 = '';
const ALL_QUESTIONS = JSON.parse(atob(B64));

let exam = [], current = 0, score = 0, answered = [];
let examTimer = null, examEndsAt = 0, examFinished = false;
const EXAM_TIME_LIMIT_MS = 2 * 60 * 60 * 1000;

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function startExam() {
  exam = shuffle(ALL_QUESTIONS).slice(0, 100);
  answered = new Array(100).fill(null);
  current = 0;
  score = 0;
  examFinished = false;
  startExamTimer();
  document.getElementById('start-screen').style.display = 'none';
  document.getElementById('results-screen').style.display = 'none';
  document.getElementById('progress-wrap').style.display = 'flex';
  document.getElementById('quiz-screen').style.display = 'block';
  renderQuestion();
  updateProgress();
}

function renderQuestion() {
  const q = exam[current];
  const ans = answered[current];
  const letters = ['A','B','C','D','E'];

  let optionsHtml = '';
  q.opts.forEach(function(opt, i) {
    let cls = 'option';
    let dis = '';
    if (ans !== null) {
      dis = 'disabled';
      if (i === ans.chosen && ans.chosen === q.c) cls += ' correct';
      else if (i === ans.chosen && ans.chosen !== q.c) cls += ' wrong';
      else if (i === q.c && ans.chosen !== q.c) cls += ' show-correct';
    }
    optionsHtml += '<button class="' + cls + '" ' + dis + ' onclick="choose(' + i + ')">' +
      '<span class="opt-letter">' + letters[i] + '</span><span>' + escHtml(opt) + '</span></button>';
  });

  let feedbackHtml = '';
  if (ans !== null) {
    if (ans.chosen === q.c) {
      feedbackHtml = '<div class="feedback ok show">&#9989; &iexcl;Correcto!</div>';
    } else {
      feedbackHtml = '<div class="feedback fail show">&#10060; Incorrecto &mdash; la respuesta correcta est&aacute; resaltada en verde.</div>';
    }
  }

  const showNext = ans !== null && current < 99;
  const showFinish = ans !== null && current === 99;

  document.getElementById('question-container').innerHTML =
    '<div class="question-card">' +
    '<div class="section-badge"><span class="bi">&#128218;</span> ' + escHtml(q.s) + '</div>' +
    '<div class="question-num">Pregunta ' + (current + 1) + ' de 100</div>' +
    '<div class="question-text">' + escHtml(q.q) + '</div>' +
    '<div class="options">' + optionsHtml + '</div>' +
    feedbackHtml +
    '</div>';

  document.getElementById('btn-next').style.display = showNext ? 'inline-block' : 'none';
  document.getElementById('btn-prev').style.display = current > 0 ? 'inline-block' : 'none';

  var finishBtn = document.getElementById('btn-finish');
  if (!finishBtn) {
    finishBtn = document.createElement('button');
    finishBtn.id = 'btn-finish';
    finishBtn.className = 'btn btn-primary';
    finishBtn.onclick = showResults;
    document.querySelector('.nav-bar').appendChild(finishBtn);
  }
  finishBtn.style.display = 'none';
  finishBtn.textContent = 'Ver Resultado';
  document.getElementById('btn-finish-any').style.display = 'inline-block';
}

function escHtml(str) {
  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function choose(idx) {
  if (answered[current] !== null) return;
  const q = exam[current];
  const isCorrect = idx === q.c;
  answered[current] = {chosen: idx, correct: isCorrect};
  if (isCorrect) score++;
  updateProgress();
  renderQuestion();
}

function nextQ() { if (current < 99) { current++; renderQuestion(); } }
function prevQ() { if (current > 0) { current--; renderQuestion(); } }

function updateProgress() {
  const done = answered.filter(function(a){ return a !== null; }).length;
  const pct = (done / 100) * 100;
  document.getElementById('progress-fill').style.width = pct + '%';
  document.getElementById('progress-label').textContent = done + ' / 100';
  document.getElementById('score-badge').textContent = '✓ ' + score;
}

function startExamTimer() {
  if (examTimer) clearInterval(examTimer);
  examEndsAt = Date.now() + EXAM_TIME_LIMIT_MS;
  updateExamTimer();
  examTimer = setInterval(updateExamTimer, 1000);
}

function updateExamTimer() {
  if (examFinished) return;
  const remaining = Math.max(0, examEndsAt - Date.now());
  const totalSeconds = Math.ceil(remaining / 1000);
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const sec = totalSeconds % 60;
  const el = document.getElementById('timer-badge');
  if (el) {
    el.textContent = '⏱ ' + String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(sec).padStart(2,'0');
    el.classList.toggle('warning', remaining <= 10 * 60 * 1000);
  }
  if (remaining <= 0) {
    clearInterval(examTimer);
    examTimer = null;
    finishExamNow(true);
  }
}

function finishExamNow(autoFinish=false) {
  if (examFinished) return;
  if (!autoFinish && !confirm('¿Seguro que deseas finalizar el examen ahora? Se calculará tu nota con las respuestas que hayas marcado.')) return;
  examFinished = true;
  if (examTimer) { clearInterval(examTimer); examTimer = null; }
  showResults(autoFinish);
}

function showResults(autoFinish=false) {
  if (window.__pnpResultLoggedExam !== exam) {
    window.__pnpResultLoggedExam = exam;
    fetch('/api/result',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(sessionStorage.getItem('pnp_auth_token')||'')},body:JSON.stringify({score:score,pct:score,correctas:score,incorrectas:100-score,exam_name:'EXAMEN PNP 2026'})}).catch(()=>{});
  }
  document.getElementById('quiz-screen').style.display = 'none';
  document.getElementById('btn-finish-any').style.display = 'none';
  document.getElementById('progress-wrap').style.display = 'none';
  document.getElementById('results-screen').style.display = 'block';
  const wrong = 100 - score;
  document.getElementById('final-score').textContent = score;
  document.getElementById('stat-correct').textContent = score;
  document.getElementById('stat-wrong').textContent = wrong;
  document.getElementById('stat-pct').textContent = score + '%';
  const circle = document.getElementById('result-circle');
  const deg = (score / 100) * 360;
  const color = score >= 65 ? '#22c55e' : score >= 50 ? '#c8a135' : '#ef4444';
  circle.style.background = 'conic-gradient(' + color + ' ' + deg + 'deg, #1e2d4a ' + deg + 'deg)';
  let title, subtitle;
  if (autoFinish) subtitle = '⏰ Se agotó el tiempo de 2 horas. Tu nota fue calculada automáticamente.';
  if (score >= 90) { title = '&#127942; Excelente'; subtitle = '&#161;Rendimiento sobresaliente! Est&#225;s muy bien preparado.'; }
  else if (score >= 65) { title = '&#9989; Aprobado'; subtitle = '&#161;Buen resultado! Sigue repasando para mejorar.'; }
  else if (score >= 50) { title = '&#9888;&#65039; Regular'; subtitle = 'Necesitas reforzar algunos temas. &#161;&#193;nimo, sigue estudiando!'; }
  else { title = '&#10060; Desaprobado'; subtitle = 'Hay que estudiar m&#225;s. Repasa el banco y vuelve a intentarlo.'; }
  if (autoFinish) subtitle = '⏰ Se agotó el tiempo de 2 horas. Tu nota fue calculada automáticamente.';
  document.getElementById('result-title').innerHTML = title;
  document.getElementById('result-subtitle').innerHTML = subtitle;
  window.scrollTo({top: 0, behavior: 'smooth'});
}
